<?php
require_once dirname(__DIR__).'/app/bootstrap.php';require_login();$uid=current_user_id();
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();$action=(string)($_POST['action']??'');
 if($action==='create'){$title=trim((string)($_POST['title']??''));$desc=trim((string)($_POST['description']??''));$visibility=(string)($_POST['visibility']??'private');if($title===''||text_len($title)>90)flash('error','Give your collection a title up to 90 characters.');else{if(!in_array($visibility,['private','unlisted','public'],true))$visibility='private';db()->prepare('INSERT INTO saved_collections(user_id,title,description,visibility,share_token) VALUES(:u,:t,:d,:v,:s)')->execute([':u'=>$uid,':t'=>$title,':d'=>text_substr($desc,0,500),':v'=>$visibility,':s'=>make_share_token()]);flash('success','Your collection was created.');}redirect(app_path('collections.php'));}
 if($action==='add'){$cid=(int)($_POST['collection_id']??0);$lid=(int)($_POST['listing_id']??0);$own=db()->prepare('SELECT id FROM saved_collections WHERE id=:c AND user_id=:u');$own->execute([':c'=>$cid,':u'=>$uid]);$listing=db()->prepare("SELECT id FROM listings WHERE id=:l AND status='published'");$listing->execute([':l'=>$lid]);if($own->fetchColumn()&&$listing->fetchColumn()){db()->prepare('INSERT OR IGNORE INTO saved_collection_items(collection_id,listing_id) VALUES(:c,:l)')->execute([':c'=>$cid,':l'=>$lid]);db()->prepare('UPDATE saved_collections SET updated_at=CURRENT_TIMESTAMP WHERE id=:c')->execute([':c'=>$cid]);flash('success','Place saved to your collection.');}else flash('error','That collection or place is unavailable.');redirect(app_path('collections.php?id='.$cid));}
 if($action==='remove'){$cid=(int)($_POST['collection_id']??0);$lid=(int)($_POST['listing_id']??0);db()->prepare('DELETE FROM saved_collection_items WHERE collection_id=:c AND listing_id=:l AND collection_id IN (SELECT id FROM saved_collections WHERE user_id=:u)')->execute([':c'=>$cid,':l'=>$lid,':u'=>$uid]);flash('success','Place removed from collection.');redirect(app_path('collections.php?id='.$cid));}
 if($action==='visibility'){$cid=(int)($_POST['collection_id']??0);$v=(string)($_POST['visibility']??'private');if(!in_array($v,['private','unlisted','public'],true))$v='private';db()->prepare('UPDATE saved_collections SET visibility=:v,updated_at=CURRENT_TIMESTAMP WHERE id=:c AND user_id=:u')->execute([':v'=>$v,':c'=>$cid,':u'=>$uid]);flash('success','Collection privacy updated.');redirect(app_path('collections.php?id='.$cid));}
 if($action==='delete'){$cid=(int)($_POST['collection_id']??0);db()->prepare('DELETE FROM saved_collections WHERE id=:c AND user_id=:u')->execute([':c'=>$cid,':u'=>$uid]);flash('success','Collection deleted.');redirect(app_path('collections.php'));}
}
$s=db()->prepare('SELECT c.*,COUNT(i.listing_id) item_count FROM saved_collections c LEFT JOIN saved_collection_items i ON i.collection_id=c.id WHERE c.user_id=:u GROUP BY c.id ORDER BY c.updated_at DESC');$s->execute([':u'=>$uid]);$collections=$s->fetchAll();$cid=(int)($_GET['id']??($collections[0]['id']??0));$active=null;$items=[];foreach($collections as $c)if((int)$c['id']===$cid)$active=$c;if($active){$s=db()->prepare("SELECT l.* FROM saved_collection_items i JOIN listings l ON l.id=i.listing_id WHERE i.collection_id=:c AND l.status='published' ORDER BY i.position,i.created_at DESC");$s->execute([':c'=>$cid]);$items=$s->fetchAll();}
$pageTitle='Saved collections | '.setting('site_name','LocalGuide');$activeNav='account';include __DIR__.'/includes/header.php';?>
<main id="main" class="container account-page lg4-page"><div class="lg4-page-heading" data-reveal="up"><span class="lg4-eyebrow">KEEP THE GOOD PLACES CLOSE</span><h1>Your collections.</h1><p>Organise places into private lists or share a curated neighbourhood shortlist.</p></div><?php if($f=get_flash()): ?><div class="alert alert-<?= h($f['type']) ?>"><?= h($f['message']) ?></div><?php endif; ?><div class="lg4-collections-layout"><aside class="content-panel lg4-side-panel"><h2>Your lists</h2><?php if($collections): ?><div class="lg4-collection-list"><?php foreach($collections as $c): ?><a class="<?= (int)$c['id']===$cid?'active':'' ?>" href="<?= app_path('collections.php?id='.(int)$c['id']) ?>"><span><i class="fa-solid fa-bookmark"></i></span><span><strong><?= h($c['title']) ?></strong><small><?= (int)$c['item_count'] ?> places · <?= h(ucfirst($c['visibility'])) ?></small></span><i class="fa-solid fa-chevron-right"></i></a><?php endforeach; ?></div><?php else: ?><p class="muted">You haven't created a collection yet.</p><?php endif; ?><hr class="soft-rule"><h3>Create a collection</h3><form method="post" class="studio-fields"><?= csrf_field() ?><input type="hidden" name="action" value="create"><label>Collection name<input name="title" maxlength="90" required placeholder="Weekend discoveries"></label><label>Description<textarea name="description" rows="3" maxlength="500" placeholder="What is this list for?"></textarea></label><label>Visibility<select name="visibility"><option value="private">Private</option><option value="unlisted">Unlisted link</option><option value="public">Public</option></select></label><button class="button button-primary button-block">Create collection</button></form></aside><section class="lg4-collection-content"><?php if($active): ?><div class="lg4-collection-head"><div><span class="lg4-eyebrow">CURATED BY YOU</span><h2><?= h($active['title']) ?></h2><p><?= h($active['description']) ?></p><small><?= count($items) ?> saved places · <?= h(ucfirst($active['visibility'])) ?></small></div><div class="lg4-collection-tools"><form method="post"><?= csrf_field() ?><input type="hidden" name="action" value="visibility"><input type="hidden" name="collection_id" value="<?= (int)$active['id'] ?>"><select name="visibility" aria-label="Collection visibility" onchange="this.form.submit()"><option value="private" <?= $active['visibility']==='private'?'selected':'' ?>>Private</option><option value="unlisted" <?= $active['visibility']==='unlisted'?'selected':'' ?>>Unlisted</option><option value="public" <?= $active['visibility']==='public'?'selected':'' ?>>Public</option></select></form><?php if($active['visibility']!=='private'): ?><button type="button" class="button button-outline button-small" data-copy-text="<?= h(collection_share_url($active)) ?>"><i class="fa-solid fa-link"></i> Copy share link</button><?php endif; ?><form method="post" onsubmit="return confirm('Delete this collection?')"><?= csrf_field() ?><input type="hidden" name="action" value="delete"><input type="hidden" name="collection_id" value="<?= (int)$active['id'] ?>"><button class="button button-outline button-small">Delete list</button></form></div></div><?php if($items): ?><div class="listing-grid lg4-listing-grid"><?php foreach($items as $listing): ?><div class="lg4-collection-item"><?php include __DIR__.'/includes/listing-card.php'; ?><form method="post" class="lg4-remove-collection"><?= csrf_field() ?><input type="hidden" name="action" value="remove"><input type="hidden" name="collection_id" value="<?= (int)$active['id'] ?>"><input type="hidden" name="listing_id" value="<?= (int)$listing['id'] ?>"><button class="text-link">Remove from list</button></form></div><?php endforeach; ?></div><?php else: ?><div class="empty-state"><span><i class="fa-regular fa-bookmark"></i></span><h3>Your collection is ready.</h3><p>Open a business profile and use Add to collection to save a place here.</p><a class="button button-primary" href="<?= app_path('index.php') ?>">Explore places</a></div><?php endif; ?><?php else: ?><div class="empty-state"><span><i class="fa-solid fa-bookmark"></i></span><h3>Create your first collection.</h3><p>Keep restaurants, hidden gems and weekend plans in one place.</p></div><?php endif; ?></section></div></main><?php include __DIR__.'/includes/footer.php';?>
